def caesar_shift(text, k):
    result_chars = []
    for char in text:
        if 'a' <= char <= 'z':
            shifted = chr(((ord(char) - ord('a') + k) % 26) + ord('a'))
            result_chars.append(shifted)
        elif 'A' <= char <= 'Z':
            shifted = chr(((ord(char) - ord('A') + k) % 26) + ord('A'))
            result_chars.append(shifted)
        else:
            result_chars.append(char)
    return ''.join(result_chars)
```

```python
def find_pair_with_sum(nums, target):
    """
    Find the first pair of indices (i, j) where i < j and nums[i] + nums[j] == target.
    Returns a tuple (i, j) or None if no such pair exists.
    """
    # Dictionary to store value -> index mapping
    seen = {}

    for i, num in enumerate(nums):
        complement = target - num
        # Check if complement exists in previously seen numbers
        if complement in seen:
            return (seen[complement], i)
        # Store the index only after checking to ensure i < j for the first pair
        # If multiple identical numbers exist, we'll keep the earliest index
        if num not in seen:
            seen[num] = i

    # No pair found
    return None
```

