def find_pair_with_sum(nums, target):
    """
    Returns the indices (i, j), i < j, of the first pair whose values add up to target.
    If no such pair exists, returns None.

    This implementation uses a hash map to achieve O(n) time complexity.
    """
    seen = {}
    for i, num in enumerate(nums):
        complement = target - num
        if complement in seen:
            return (seen[complement], i)
        if num not in seen:  # Store first occurrence only, to ensure first pair by i
            seen[num] = i
    return None
