```python
import random
from typing import List, TypeVar

T = TypeVar('T')

def kth_smallest(items: List[T], k: int) -> T:
    """
    Find the k-th smallest element in an unsorted list (1-indexed).
    """
    if not 1 <= k <= len(items):
        raise IndexError("k is out of bounds")

    def quickselect(lst, k):
        if len(lst) == 1:
            return lst[0]

        pivot = random.choice(lst)

        less = [x for x in lst if x < pivot]
        equal = [x for x in lst if x == pivot]
        greater = [x for x in lst if x > pivot]

        L, E = len(less), len(equal)

        if k <= L:
            return quickselect(less, k)
        elif k <= L + E:
            return pivot
        else:
            return quickselect(greater, k - L - E)

    return quickselect(items, k)
```

