def longest_run(lst):
    """
    Returns the length of the longest run of equal consecutive elements in a list.
    Returns 0 for an empty list.
    """
    if not lst:
        return 0

    max_run = 1
    current_run = 1

    for i in range(1, len(lst)):
        if lst[i] == lst[i - 1]:
            current_run += 1
        else:
            if current_run > max_run:
                max_run = current_run
            current_run = 1

    # Check the last run
    if current_run > max_run:
        max_run = current_run

    return max_run
