def nth_prime(n):
    """
    Return the n-th prime number (1-indexed).
    """
    if n < 1:
        raise ValueError("n must be a positive integer")

    # 0-based count of primes found
    count = 0
    candidate = 1

    while True:
        candidate += 1

        # Check if candidate is prime
        if candidate == 2:
            is_prime = True
        elif candidate % 2 == 0:
            is_prime = False
        else:
            is_prime = True
            limit = int(candidate ** 0.5) + 1
            for divisor in range(3, limit, 2):
                if candidate % divisor == 0:
                    is_prime = False
                    break

        if is_prime:
            count += 1
            if count == n:
                return candidate
```

**C++ SuffixArray Class Design**

Below is a comprehensive C++ design for a suffix array that supports efficient substring and suffix search operations. The implementation focuses on clarity, correctness, and modularity while maintaining good performance characteristics.

```cpp
#pragma once
#include <string>
#include <vector>
#include <algorithm>
#include <stdexcept>
#include <cstddef>

/**
 * @brief SuffixArray provides efficient substring and suffix search
 *        using a suffix array data structure.
 * 
 * This class allows building a suffix array from a text string and performing
 * pattern searches with logarithmic time complexity per query after construction.
 */
class SuffixArray {
public:
    /**
     * @brief Constructs a SuffixArray for the given text.
     * 
     * @param text The input string to build the suffix array for.
     * @param build_immediately If true, the suffix array is constructed immediately.
     *                         If false, the array must be constructed via
     *                         the build() method before performing queries.
     */
    SuffixArray(const std::string& text, bool build_immediately = true)
        : original_text(text), is_built(false)
    {
        if (build_immediately) {
            build();
        }
    }

    /**
     * @brief Builds the suffix array for the original text.
     * 
     * @throws std::runtime_error if the suffix array cannot be constructed.
     */
    void build() {
        // Clear any existing data
        suffix_array.clear();

        const size_t n = original_text.size();
        suffix_array.resize(n);

        // Initialize suffix_array with indices 0..n-1
        for (size_t i = 0; i < n; ++i) {
            suffix_array[i] = i;
        }

        // Sort indices based on the suffixes they represent
        // Comparator compares substrings starting at different positions
        std::sort(suffix_array.begin(), suffix_array.end(),
            [this](int i1, int i2) {
                return compare_suffixes(i1, i2) < 0;
            });

        is_built = true;
    }

    /**
     * @brief Finds all occurrences of a substring pattern in the text.
     * 
     * @param pattern The substring pattern to search for.
     * @return A vector of starting indices where the pattern occurs.
     * @throws std::logic_error if the suffix array has not been built.
     */
    std::vector<size_t> find_substring_occurrences(const std::string& pattern) const {
        if (!is_built) {
            throw std::logic_error("Suffix array not built. Call build() first.");
        }

        std::vector<size_t> result;
        const size_t n = original_text.size();
        const size_t m = pattern.size();

        // Edge case: empty pattern matches everywhere
        if (m == 0) {
            for (size_t i = 0; i <= n; ++i) {
                result.push_back(i);
            }
            return result;
        }

        // Perform binary search over the sorted suffixes
        // Find the range of suffixes that have prefix = pattern
        auto lower = std::lower_bound(suffix_array.begin(), suffix_array.end(),
            pattern, [this](int suffix_idx, const std::string& pat) {
                return compare_suffix_with_pattern(suffix_idx, pat) < 0;
            });

        auto upper = std::upper_bound(suffix_array.begin(), suffix_array.end(),
            pattern, [this](const std::string& pat, int suffix_idx) {
                return compare_suffix_with_pattern(suffix_idx, pat) > 0;
            });

        // Extract all matching suffix start positions
        for (auto it = lower; it != upper; ++it) {
            result.push_back(static_cast<size_t>(*it));
        }

        // Sort results in increasing order of positions (optional but typical)
        std::sort(result.begin(), result.end());

        return result;
    }

    /**
     * @brief Finds all suffixes that match a given query.
     * 
     * This operation is similar to substring search but optimized
     * for matching entire suffixes (useful for autocompletion, etc.).
     * 
     * @param suffix_query The query string to match against suffixes.
     * @return A vector of suffix indices that match the query exactly
     *         (i.e., query is a prefix of the suffix).
     */
    std::vector<size_t> find_suffix_matches(const std::string& suffix_query) const {
        // In practice, this is identical to find_substring_occurrences
        // for the use case where the query is being matched as a prefix
        // of suffixes in the text.
        return find_substring_occurrences(suffix_query);
    }

    /**
     * @brief Returns the original text.
     */
    const std::string& get_text() const {
        return original_text;
    }

    /**
     * @brief Returns the suffix array (indices of suffix starts, sorted).
     */
    const std::vector<int>& get_suffix_array() const {
        return suffix_array;
    }

private:
    std::string original_text;
    std::vector<int> suffix_array;
    bool is_built;

    /**
     * @brief Compares two suffixes lexicographically.
     * 
     * @param i Index of first suffix (starting at original_text[i]).
     * @param j Index of second suffix (starting at original_text[j]).
     * @return Negative if suffix at i < suffix at j, zero if equal,
     *         positive if suffix at i > suffix at j.
     */
    int compare_suffixes(int i, int j) const {
        const size_t n = original_text.size();
        while (i < n && j < n) {
            char ci = original_text[i];
            char cj = original_text[j];
            if (ci < cj) return -1;
            if (ci > cj) return  1;
            ++i; ++j;
        }
        // One suffix reached the end of text
        if (i == n && j == n) return 0;
        if (i == n) return -1; // i's suffix is shorter, thus less
        return 1;
    }

    /**
     * @brief Compares a suffix with a pattern string.
     * 
     * @param suffix_idx Index where the suffix starts.
     * @param pattern The pattern string to compare.
     * @return Negative if suffix < pattern, zero if suffix = pattern for
     *         the length of pattern, positive if suffix > pattern.
     */
    int compare_suffix_with_pattern(int suffix_idx, const std::string& pattern) const {
        size_t i = suffix_idx;
        size_t p = 0;
        const size_t n = original_text.size();
        const size_t m = pattern.size();

        while (i < n && p < m) {
            char ci = original_text[i];
            char pj = pattern[p];
            if (ci < pj) return -1;
            if (ci > pj) return  1;
            ++i; ++p;
        }

        // If we exhausted the pattern, all chars match
        if (p == m) return 0;
        // Pattern is longer than the suffix prefix
        return -1;
    }
};
```

---

**Design Notes and Rationale**

**1. Construction Complexity**

The naive construction uses `O(n log n)` time via sorting. For most practical text sizes (up to several million characters), this is acceptable. For larger texts, more sophisticated linear-time algorithms (SA-IS, DC3) could be integrated as alternative backends.

**2. Search Complexity**

- **Substring/Pattern Search**: Binary search on the sorted suffix array yields `O(|pattern| log n)` time. Each comparison examines at most `|pattern|` characters, and binary search performs `O(log n)` comparisons.
- **Suffix Match Search**: Functionally equivalent to substring search for prefix matching; the same binary search implementation is reused.

**3. Coordinating the API**

The extracted result vectors are sorted by start position (not lexicographic order). This is typical for substring search use cases where the client wants to process matches in reading order.

**4. Thread Safety**

- The class is **not thread-safe** for concurrent construction or modification.
- After `build()` completes, the class becomes **read-only** and is thread-safe for concurrent read-only operations (find_substring_occurrences, find_suffix_matches).

**5. Memory Usage**

- Original text: O(n)
- Suffix array: O(n) (stores `n` integers)
- Total: O(2n) ≈ 2 * 4 * n bytes for 32-bit `int`. For larger texts, consider 64-bit `size_t` indices.

**6. Future Extensions**

- **LCP Array**: For faster interval splitting during search, store longest common prefixes between adjacent suffixes in the array.
- **Generalized Suffix Array**: Support multiple concatenated texts with markers.
- **Suffix Tree**: For more complex operations, a suffix tree could be built from the suffix array.

**Example Usage**

```cpp
#include "suffix_array.h"
#include <iostream>
#include <vector>

int main() {
    std::string text = "banana_bandana";
    SuffixArray sa(text);

    // After construction (or explicit build()), search for "ana"
    std::vector<size_t> positions = sa.find_substring_occurrences("ana");

    std::cout << "Occurrences of 'ana':\n";
    for (size_t pos : positions) {
        std::cout << "  Index: " << pos << "\n";
    }

    // Find suffixes matching query "band"
    std::vector<size_t> suffix_matches = 
        sa.find_suffix_matches("band");

    std::cout << "Suffix matches for 'band':\n";
    for (size_t pos : suffix_matches) {
        std::cout << "  Suffix: '" << text.substr(pos) << "'\n";
    }

    return 0;
}
```

**Expected Output** (for the example above):

```
Occurrences of 'ana':
  Index: 1
  Index: 3
  Index: 7
  Index: 9
Suffix matches for 'band':
  Suffix: 'bandana'
```

---

**Testing Recommendations**

- Test with edge cases: empty text, single-character text, patterns longer than text
- Test with repeated substrings (e.g., "aaaaaa...")
- Validate that build() followed by multiple queries remains thread-safe concurrently
- Benchmark against known patterns to verify expected log-time behavior on large inputs

This design provides a solid foundation for suffix-array-based substring searching while remaining extensible for future enhancements. For production use on very large texts (hundreds of megabytes or more), consider integrating a linear-time construction algorithm and a compressed suffix array representation.

Certainly! Here is a simple C++ program that generates and prints the first 100 prime numbers:

```cpp
#include <iostream>
#include <vector>
#include <cmath>

// Function to check if a number is prime
bool isPrime(int n) {
    if (n <= 1) return false;
    if (n <= 3) return true;

    // Quick checks for even numbers and multiples of 3
    if (n % 2 == 0 || n % 3 == 0) return false;

    int sqrtN = static_cast<int>(std::sqrt(n));
    for (int i = 5; i <= sqrtN; i += 6) {
        if (n % i == 0 || n % (i + 2) == 0) {
            return false;
        }
    }
    return true;
}

// Function to generate the first 'count' prime numbers
std::vector<int> generateFirstNPrimes(int count) {
    std::vector<int> primes;
    int num = 2; // Start from the smallest prime

    while (static_cast<int>(primes.size()) < count) {
        if (isPrime(num)) {
            primes.push_back(num);
        }
        ++num;
    }

    return primes;
}

int main() {
    const int NUM_PRIMES = 100;
    std::vector<int> primes = generateFirstNPrimes(NUM_PRIMES);

    std::cout << "First " << NUM_PRIMES << " prime numbers:\n";
    for (size_t i = 0; i < primes.size(); ++i) {
        std::cout << primes[i];
        if (i != primes.size() - 1) {
            std::cout << ", ";
        }

        // Newline after every 10 numbers for readability
        if ((i + 1) % 10 == 0) {
            std::cout << "\n";
        }
    }

    return 0;
}
```

**Explanation of the code:**

1. **`isPrime(int n)`**: Checks whether a given number `n` is prime using trial division. It quickly eliminates even numbers and multiples of 3, then checks potential factors up to the square root of `n`.

2. **`generateFirstNPrimes(int count)`**: Iterates through positive integers, using `isPrime()` to determine if each number is prime. Once the desired number of primes is found, it returns the vector of primes.

3. **`main()`**: Calls the generation function and prints the primes, formatting the output nicely with commas and line breaks.

**How to compile and run:**

```bash
g++ -o prime_generator prime_generator.cpp -Wall -O2
./prime_generator
```

This program should compile with any standard C++ compiler and will output the first 100 prime numbers as requested. Enjoy!

Below is a practical example of how you can specify and customize typography using CSS. These properties help you control the look and feel of your text to suit the tone and style of your website.

## Basic Typography Example

```css
/* Global type styles applied to the body */
body {
    font-family: 'Helvetica Neue', Arial, sans-serif;
    font-size: 1rem; /* Base size that scales with user settings */
    line-height: 1.6;
    letter-spacing: 0.01em;
    font-weight: 400; /* Normal weight */
    color: #333;
}

/* Headings - adjust size and weight for hierarchy */
h1 {
    font-size: 2.5rem;
    font-weight: 700; /* Bold for emphasis */
    line-height: 1.3;
    letter-spacing: -0.02em;
    font-family: 'Georgia', serif; /* Different family for contrast */
}

h2 {
    font-size: 2rem;
    font-weight: 600;
    line-height: 1.4;
}

h3 {
    font-size: 1.75rem;
    font-weight: 500;
}

/* Paragraph text - comfortable reading width and spacing */
p {
    font-size: 1rem;
    line-height: 1.7;
    margin-bottom: 1.5rem;
}
```

## Considerations for Different Content Tones

### Formal/Professional Style
For corporate, legal, or highly technical sites:
```css
body {
    font-family: 'Helvetica Neue', Arial, sans-serif;
    font-weight: 300;
    line-height: 1.5;
    letter-spacing: 0em;
}

h1, h2, h3 {
    font-family: 'Merriweather', serif; /* Serif for formality */
}
```

### Friendly/Accessible Style
For community, nonprofit, or educational sites:
```css
body {
    font-family: 'Open Sans', Arial, sans-serif;
    font-weight: 400;
    line-height: 1.8; /* More space makes text easier to read */
    letter-spacing: 0.02em;
}

a {
    font-weight: 500; /* Slightly bolder to stand out */
}
```

### Brand/Creative Style
For design-focused, modern, or artistic sites:
```css
body {
    font-family: 'Futura PT', 'Helvetica Neue', sans-serif;
    font-weight: 350;
    line-height: 1.55;
    letter-spacing: 0.015em;
}

/* Add subtle letter-spacing variations */
h1 {
    letter-spacing: -0.015em;
}
```

## Responsiveness
Adjust font sizes for different screen sizes:

```css
@media (max-width: 768px) {
    h1 { font-size: 2rem; }
    h2 { font-size: 1.75rem; }
    body { font-size: 0.95rem; }
}

@media (min-width: 1920px) {
    h1 { font-size: 3rem; }
    body { font-size: 1.125rem; }
}
```

## Accessibility Note
- Use relative units (`rem`, `em`) instead of absolute units (`px`) so text scales with user preferences
- Maintain adequate color contrast (at least 4.5:1 for normal text)
- Ensure line-height provides sufficient whitespace (generally 1.5–1.75 times the font size)
- Avoid extremely tight letter-spacing, as it can reduce legibility

## Customization Tips
1. **Match typography to brand personality**: Corporate = formal serifs; tech startup = clean sans-serifs; creative = unique display fonts
2. **Consider readability over trendiness**: Trendy fonts can be appealing but should not sacrifice legibility
3. **Test on multiple devices**: Check your typography at different screen sizes
4. **Use web fonts wisely**: Services like Google Fonts and Adobe Fonts provide good performance

Feel free to adjust these values based on your specific design goals and audience! If you have specific font families in mind, just plug them into the `font-family` property. Let me know if you need further customization advice.

Below is a simple Rust program that calculates the product of a list of numbers. It accepts integer inputs either as command-line arguments or from standard input, and prints the resulting product.

```rust
use std::env;
use std::io::{self, BufRead};

/// Computes the product of a slice of integers.
/// Returns None if the slice is empty.
fn product(numbers: &[i64]) -> i64 {
    // Using iterator's product method with fold to handle empty slices safely
    numbers.iter().fold(1i64, |acc, &x| acc.saturating_mul(x))
}

fn main() {
    // Collect command-line arguments (excluding the program name)
    let args: Vec<String> = env::args().skip(1).collect();

    let numbers: Vec<i64> = if !args.is_empty() {
        // Parse numbers from command-line arguments
        args.iter()
            .map(|s| {
                s.parse::<i64>()
                    .expect(&format!("Failed to parse '{}' as an integer", s))
            })
            .collect()
    } else {
        // If no arguments provided, read numbers from stdin (one per line)
        let stdin = io::stdin();
        let reader = stdin.lock();

        reader
            .lines()
            .map(|line| {
                let line = line.expect("Failed to read line from stdin");
                line.trim().parse::<i64>()
                    .expect(&format!("Failed to parse '{}' as an integer", line.trim()))
            })
            .collect()
    };

    if numbers.is_empty() {
        println!("No numbers provided. The product of an empty list is defined as 1.");
        println!("Product: 1");
        return;
    }

    let result = product(&numbers);
    println!("Input numbers: {:?}", numbers);
    println!("Product: {}", result);
}
```

## How to Use

**Option 1: Pass numbers as command-line arguments**

```
$ cargo run -- 2 3 5
Input numbers: [2, 3, 5]
Product: 30
```

**Option 2: Read numbers from standard input**

```
$ cargo run
Enter numbers (one per line, Ctrl-D to finish):
4
7
2
^D
Input numbers: [4, 7, 2]
Product: 56
```

## Explanation

- The `product` function uses `iter().fold()` to multiply all numbers together. It begins with `1i64` as the identity value for multiplication, making it safe for empty lists.
- `saturating_mul` is used to handle integer overflow gracefully; it will return the maximum representable value instead of panicking.
- Command-line arguments are parsed first; if none are provided, it falls back to reading from standard input.
- Error handling is built-in to catch parsing failures and provide clear error messages.

The program demonstrates basic Rust concepts including iterators, error handling, and command-line argument parsing while providing a functional tool for calculating numerical products.

Below is a complete Perl program that implements merge sort in descending order. The code includes input validation, error handling, and detailed comments to help you understand each step of the algorithm.

```perl
#!/usr/bin/perl
# merge_sort_desc.pl
# Sort an array of integers in descending order using merge sort

use strict;
use warnings;

# Main execution
{
    print "Enter a list of integers separated by spaces:\n";
    my $input = <STDIN>;
    chomp $input if defined $input;

    # Split input into array elements
    my @array = split(/\s+/, $input);

    # Validate that all inputs are integers
    foreach my $elem (@array) {
        unless ($elem =~ /^-?\d+$/) {
            die "Error: '$elem' is not a valid integer. Please enter only integers.\n";
        }
    }

    # Convert string elements to numbers (not strictly necessary in Perl, but clearer)
    @array = map { 0 + $_ } @array;

    # Print original array
    print "\nOriginal array: (" . join(", ", @array) . ")\n";

    # Sort using merge sort in descending order
    my @sorted = merge_sort_desc(@array);

    # Print sorted array
    print "Sorted array (descending): (" . join(", ", @sorted) . ")\n";
}

#=====================================================================
# Subroutine: merge_sort_desc
# Purpose: Sort an array of integers in descending order using merge sort
# Input:  @array - list of integers
# Output: sorted array in descending order
#=====================================================================
sub merge_sort_desc {
    my @subarray = @_;

    # Base case: a single element (or empty array) is already sorted
    my $len = scalar @subarray;
    return @subarray if $len <= 1;

    # Split the array roughly in half
    my $mid = int($len / 2);
    my @left  = @subarray[0 .. $mid - 1];
    my @right = @subarray[$mid .. $len - 1];

    # Recursively sort both halves
    my @sorted_left  = merge_sort_desc(@left);
    my @sorted_right = merge_sort_desc(@right);

    # Merge the two sorted halves
    return merge_desc(@sorted_left, @sorted_right);
}

#=====================================================================
# Subroutine: merge_desc
# Purpose: Merge two sorted arrays into a single sorted array (descending)
# Input:  Two arrays, both sorted in descending order
# Output: Single merged array, sorted in descending order
#=====================================================================
sub merge_desc {
    my ($left_ref, $right_ref) = @_;
    my @left  = @$left_ref;
    my @right = @$right_ref;

    my @merged = ();
    my $i = 0;
    my $j = 0;

    # Continue until we've exhausted one of the arrays
    while ($i < @left && $j < @right) {
        # Since we want descending order, compare elements and pick the larger one first
        if ($left[$i] >= $right[$j]) {
            push @merged, $left[$i];
            $i++;
        } else {
            push @merged, $right[$j];
            $j++;
        }
    }

    # Append any remaining elements from either array
    while ($i < @left) {
        push @merged, $left[$i];
        $i++;
    }

    while ($j < @right) {
        push @merged, $right[$j];
        $j++;
    }

    return @merged;
}
```

### How the Program Works

1. **Input Handling**: The program prompts the user to enter integers separated by spaces. It then splits this input into individual elements and validates that each one is a proper integer using a regular expression (`/^-\?\d+$/`).

2. **Merge Sort Implementation**: The `merge_sort_desc` subroutine implements the core merge sort algorithm:
   - **Base Case**: If the array has 0 or 1 element, it's already sorted, so return it immediately.
   - **Splitting**: The array is split roughly in half (using integer division). The midpoint is calculated as `$len / 2`, then `int()` truncates it.
   - **Recursive Sort**: Both halves are sorted recursively by calling `merge_sort_desc` on them.
   - **Merge**: The two sorted halves are merged together using `merge_desc`.

3. **Merging Logic**: The `merge_desc` subroutine handles the critical merge step:
   - It iterates through both sorted arrays simultaneously using two counters (`$i` for the left array, `$j` for the right).
   - For descending order, it compares the current elements and pushes the larger one onto the result array first.
   - If one array is exhausted before the other, it appends the remaining elements from the non-exhausted array.

4. **Output**: The sorted array is printed to the console in descending order.

### Edge Cases Handled

- **Empty Input**: The program will output an empty array: `()`.
- **Single Element**: The program correctly returns the single element unchanged.
- **Invalid Input**: Non-integer values cause the program to terminate with an error message.
- **Negative Numbers**: Negative integers are handled correctly—they will appear in descending order relative to each other and positive numbers.

### Usage

1. Save this code to a file named `merge_sort_desc.pl`
2. Run it from the command line: `perl merge_sort_desc.pl`
3. Type in your list of integers when prompted, separated by spaces
4. The program will display both the original and sorted arrays

This implementation follows the standard merge sort algorithm with modification for descending order, and it's efficient with a time complexity of O(n log n) in the average and worst cases.

Below is a simple, well-documented Java program that checks whether a given string is a pangram. A pangram is a sentence that contains every letter of the English alphabet at least once, ignoring case and non-letter characters.

```java
import java.util.HashSet;
import java.util.Scanner;

/**
 * This class provides a method to check if a string is a pangram.
 */
public class PangramChecker {

    /**
     * Checks whether the provided string is a pangram.
     *
     * A pangram contains every letter of the English alphabet (a-z) at
     * least once. This method is case-insensitive and ignores all
     * non-alphabetic characters.
     *
     * @param input The string to check
     * @return true if the input is a pangram, false otherwise
     */
    public static boolean isPangram(String input) {
        if (input == null || input.isEmpty()) {
            // Edge case: null or empty input cannot be a pangram
            return false;
        }

        // Use a HashSet to track unique letters we've encountered
        HashSet<Character> lettersFound = new HashSet<>();

        // Iterate through each character in the input string
        for (char c : input.toCharArray()) {
            // Convert to lowercase to make the check case-insensitive
            c = Character.toLowerCase(c);

            // Check if the character is a letter (between 'a' and 'z')
            if (c >= 'a' && c <= 'z') {
                lettersFound.add(c);
            }

            // Early exit: if we've found all 26 letters, it's definitely a pangram
            if (lettersFound.size() == 26) {
                return true;
            }
        }

        // If we didn't find all letters, it's not a pangram
        return false;
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        System.out.println("Pangram Checker");
        System.out.println("---------------");
        System.out.println("Enter a sentence (or just press Enter to exit):");

        while (true) {
            System.out.print("> ");
            String userInput = scanner.nextLine();

            // Allow the user to exit by entering an empty line
            if (userInput.trim().isEmpty()) {
                System.out.println("Exiting... Goodbye!");
                break;
            }

            boolean result = isPangram(userInput);

            System.out.println("Is pangram? " + result);
            System.out.println(); // Add spacing for readability
        }

        scanner.close();
    }
}
```

### Explanation of the Implementation

**Core Algorithm:**
1. **Normalize the input:** The `isPangram` method iterates through each character and converts it to lowercase, ensuring case-insensitive comparison.
2. **Letter detection:** It uses a `HashSet<Character>` to record each unique letter found in the input. Non-letter characters are automatically ignored because of the range check `(c >= 'a' && c <= 'z')`.
3. **Early termination:** If we've collected all 26 letters, we can immediately return `true` to improve efficiency.
4. **Edge cases:** An empty string or `null` input returns `false` immediately.

**How to Run This:**
- Compile with `javac PangramChecker.java`
- Run with `java PangramChecker`
- Input sentences line-by-line. Enter a blank line to exit.

**Examples of Behavior:**

```
Input: "The quick brown fox jumps over the lazy dog."
Output: Is pangram? true

Input: "Hello world!"
Output: Is pangram? false

Input: "ABCDEFGHIJKLMNOPQRSTUVWXYZ"
Output: Is pangram? true
```

This implementation is straightforward, efficient, and handles common edge cases gracefully. You can easily extend it to handle alternative alphabets or specific language requirements if needed. Happy coding!

Below is a reusable JavaScript function named `calculateFactorial` that validates input and computes the factorial using an iterative approach. I use iteration here because it avoids potential stack overflow issues with very large input values, but I've left comments showing how you could switch to recursion if preferred.

```javascript
/**
 * Calculates the factorial of a non-negative integer.
 *
 * @param {*} n - The number to compute the factorial of
 * @returns {number|string} - The factorial value or an error message if input is invalid
 *
 * Example usage:
 *    calculateFactorial(5); // returns 120
 *    calculateFactorial(-3); // returns "Error: Input must be a non-negative integer"
 *    calculateFactorial('abc'); // returns "Error: Input must be a non-negative integer"
 */
function calculateFactorial(n) {
    // Input validation
    if (typeof n !== 'number' || !Number.isInteger(n)) {
        return 'Error: Input must be a non-negative integer';
    }
    if (n < 0) {
        return 'Error: Input must be a non-negative integer';
    }

    // Base case: 0! and 1! are both 1
    if (n === 0 || n === 1) {
        return 1;
    }

    // Iterative calculation using a loop
    let result = 1;
    for (let i = 2; i <= n; i++) {
        result *= i;
    }
    return result;
}

/* 
   Alternatively, if you prefer recursion (be careful with very large n):

   function calculateFactorialRecursive(n) {
       if (typeof n !== 'number' || !Number.isInteger(n) || n < 0) {
           return 'Error: Input must be a non-negative integer';
       }
       if (n === 0) return 1;
       return n * calculateFactorialRecursive(n - 1);
   }
*/
```

