    def __init__(self, N):
        self.N = N
        self.graph = [[] for _ in range(N)]
        self.level = [0] * N
        self.it = [0] * N

    def add_edge(self, fr, to, cap):
        forward = Edge(to, len(self.graph[to]), cap)
        backward = Edge(fr, len(self.graph[fr]), 0)
        self.graph[fr].append(forward)
        self.graph[to].append(backward)

    def bfs(self, s, t):
        self.level = [-1] * self.N
        q = deque([s])
        self.level[s] = 0
        while q:
            v = q.popleft()
            for e in self.graph[v]:
                if e.cap > 0 and self.level[e.to] < 0:
                    self.level[e.to] = self.level[v] + 1
                    q.append(e.to)
        return self.level[t] >= 0

    def dfs(self, v, t, f):
        if v == t:
            return f
        for i in range(self.it[v], len(self.graph[v])):
            e = self.graph[v][i]
            if e.cap > 0 and self.level[v] < self.level[e.to]:
                d = self.dfs(e.to, t, min(f, e.cap))
                if d > 0:
                    e.cap -= d
                    self.graph[e.to][e.rev].cap += d
                    return d
            self.it[v] += 1
        return 0

    def max_flow(self, s, t, max_needed=None):
        flow = 0
        INF = 10**18
        while self.bfs(s, t):
            self.it = [0] * self.N
            while True:
                f = self.dfs(s, t, INF if max_needed is None else min(INF, max_needed - flow))
                if f == 0:
                    break
                flow += f
                if max_needed is not None and flow >= max_needed:
                    return flow
        return flow

