class LiChaoTree:
    def __init__(self, x_left, x_right):
        self.root = LiChaoNode(x_left, x_right)

    def insert(self, line):
        self._insert(self.root, line)

    def _insert(self, node, new_line):
        l, r = node.l, node.r
        mid = (l + r) // 2

        if node.line is None:
            node.line = new_line
            return

        left_is_better = new_line.value(l) < node.line.value(l)
        mid_is_better = new_line.value(mid) < node.line.value(mid)

        if mid_is_better:
            node.line, new_line = new_line, node.line

        if l == r:
            return

        if left_is_better != mid_is_better:
            if node.left is None:
                node.left = LiChaoNode(l, mid)
            self._insert(node.left, new_line)
        else:
            if node.right is None:
                node.right = LiChaoNode(mid + 1, r)
            self._insert(node.right, new_line)

    def query(self, x):
        return self._query(self.root, x)

    def _query(self, node, x):
        if node is None:
            return float('inf')
        res = node.line.value(x) if node.line else float('inf')
        mid = (node.l + node.r) // 2
        if x <= mid:
            return min(res, self._query(node.left, x))
        else:
            return min(res, self._query(node.right, x))

