class Solution:
    def longestPalindromicSubsequence(self, s: str, k: int) -> int:
        """
        Compute the longest palindromic subsequence length achievable after at most
        k character shift operations, where each operation can shift a letter by one
        step forward or backward around the alphabet with wrap-around.
        """
        n = len(s)
        if n == 0:
            return 0

        # Precompute circular distances between letters
        def circular_dist(c1, c2):
            d = abs(ord(c1) - ord(c2))
            return min(d, 26 - d)

        # dp[l][r][c] = max palindrome length in s[l:r+1] using exactly c operations
        dp = [[[0] * (k + 1) for _ in range(n)] for _ in range(n)]

        # Base case: single character substrings
        for i in range(n):
            for c in range(k + 1):
                dp[i][i][c] = 1

        # Process substrings of increasing length
        for length in range(2, n + 1):
            for l in range(n - length + 1):
                r = l + length - 1
                pair_cost = circular_dist(s[l], s[r])
                for used in range(k + 1):
                    # Option 1: skip either end
                    best = dp[l + 1][r][used]
                    if dp[l][r - 1][used] > best:
                        best = dp[l][r - 1][used]

                    # Option 2: pair l and r (needs cost pair_cost)
                    if used >= pair_cost:
                        if l + 1 > r - 1:
                            inner = 0
                        else:
                            inner = dp[l + 1][r - 1][used - pair_cost]
                        if inner + 2 > best:
                            best = inner + 2

                    dp[l][r][used] = best

        # Result: max length using up to k operations
        return max(dp[0][n - 1][c] for c in range(k + 1))


