class Solution:
    def longestPalindrome(self, s: str, t: str) -> int:
        """
        Returns the length of the longest palindrome that can be formed by
        concatenating a substring from s and a substring from t.
        """

        def get_substrings(st: str) -> list:
            """Generate all possible substrings of a string, including empty."""
            n = len(st)
            substrings = [""]
            for i in range(n):
                for j in range(i + 1, n + 1):
                    substrings.append(st[i:j])
            return substrings

        subs_s = get_substrings(s)
        subs_t = get_substrings(t)

        max_len = 0

        # Check all combinations of substrings from s and t
        for sub_s in subs_s:
            for sub_t in subs_t:
                total_len = len(sub_s) + len(sub_t)

                # Only check palindrome if this length beats current max
                if total_len <= max_len:
                    continue

                combined = sub_s + sub_t
                if combined == combined[::-1]:
                    max_len = total_len

        # At minimum there is always a single character palindrome
        if max_len == 0:
            return 1

        return max_len

