class FenwickTree:
    def __init__(self, n):
        self.n = n
        self.bit = [0] * (n + 1)

    def add(self, idx, val):
        while idx <= self.n:
            self.bit[idx] += val
            idx += idx & -idx

    def sum(self, idx):
        s = 0
        while idx > 0:
            s += self.bit[idx]
            idx -= idx & -idx
        return s

    def find_kth(self, k):
        """Find smallest index such that prefix sum >= k (1-indexed)."""
        idx = 0
        bit_mask = 1 << (self.n.bit_length())  # start with largest power of 2 <= n
        while bit_mask:
            next_idx = idx + bit_mask
            if next_idx <= self.n and self.bit[next_idx] < k:
                k -= self.bit[next_idx]
                idx = next_idx
            bit_mask >>= 1
        return idx + 1  # +1 because idx is the last with sum < target

