class SegmentTree:
    def __init__(self, data):
        """Build segment tree for range max with lazy add."""
        self.n = len(data)
        self.size = 1
        while self.size < self.n:
            self.size <<= 1
        self.max_tree = [float('-inf')] * (2 * self.size)
        self.lazy = [0] * (2 * self.size)
        for i in range(self.n):
            self.max_tree[self.size + i] = data[i]
        for i in range(self.size - 1, 0, -1):
            self.max_tree[i] = max(self.max_tree[2 * i], self.max_tree[2 * i + 1])

    def _push(self, node):
        """Push lazy updates to children."""
        if self.lazy[node] != 0:
            for child in (2 * node, 2 * node + 1):
                self.max_tree[child] += self.lazy[node]
                self.lazy[child] += self.lazy[node]
            self.lazy[node] = 0

    def _range_add(self, l, r, val, node, node_l, node_r):
        if r < node_l or node_r < l:
            return
        if l <= node_l and node_r <= r:
            self.max_tree[node] += val
            self.lazy[node] += val
            return
        self._push(node)
